#pragma once
#include <samplerate.h>
#include <sqlite3.h>
int runSimilarity431(){
 juce::ScopedJuceInitialiser_GUI gui;LibraryPreparation::checksPaused=true;std::cout.setf(std::ios::unitbuf);
 auto require=[](bool ok,const char* why){if(!ok)throw std::runtime_error(why);};
 auto wait=[](auto predicate){double until=juce::Time::getMillisecondCounterHiRes()+60000;while(!predicate()&&juce::Time::getMillisecondCounterHiRes()<until){CFRunLoopRunInMode(kCFRunLoopDefaultMode,.002,true);juce::Thread::sleep(2);}return predicate();};
 try{
  using Mode=DrumSimilarity::Mode;using Features=DrumSimilarity::Features;
  Features ref,a,b;ref.sound[0]=1;a.sound[0]=.8f;a.sound[1]=.6f;b.sound[0]=.6f;b.sound[2]=.8f;a.dynamics.fill(2);std::vector<std::pair<juce::String,Features>> synthetic{{"A",a},{"B",b}};
  auto drum=DrumSimilarity::rank(ref,synthetic,Mode::Drums),general=DrumSimilarity::rank(ref,synthetic,Mode::General);require(drum.at("B")<drum.at("A")&&general.at("A")<general.at("B"),"general prioritises sound over envelope");auto tolerant=DrumSimilarity::rank(ref,synthetic,Mode::General,{b.sound});require(tolerant.at("B")<general.at("B"),"pitch alternative improves neural match");
  require(DrumSimilarity::rank(ref,synthetic,Mode::General,{b.sound},[]{return true;}).empty(),"ranking cancellation returns no partial results");
  auto root=LibraryStore::root(),folder=root.getChildFile("Non-drum examples");folder.createDirectory();
  auto chords=juce::File("/Users/duncanmaclennan/Dropbox/D SAMPLES/ONE SHOTS/CHORD/Big Fish Audio - Old Skool House CHORD ONE SHOTS");
  juce::Array<juce::File> sources{
   juce::File("/Users/duncanmaclennan/Dropbox/D SAMPLES/SAMPLE PACKS/HYP JMH/melodic loops/synth loops/JMH_132_Dm_Organ_Synth.wav"),
   chords.getChildFile("Lush Pad 2 Chord C3 [2026-01-08 082552] - C3 - C.wav"),
   chords.getChildFile("Dirty Piano C3 [2026-01-08 082550] - C3 - Cm.wav"),
   chords.getChildFile("80s Bell Piano Chord Norm [2026-01-08 082439] - C3 - C.wav")};
  juce::Array<juce::File> files;for(auto source:sources){auto f=folder.getChildFile(source.getFileName());require(source.copyFileTo(f),"copy non-drum source");files.add(f);}
  // A real organ sound transposed seven semitones; this is an objective pitch-tolerance control.
  juce::AudioFormatManager formats;formats.registerBasicFormats();std::unique_ptr<juce::AudioFormatReader> reader(formats.createReaderFor(files[0]));require(reader!=nullptr,"organ reader");int length=(int)std::min<int64_t>(reader->lengthInSamples,(int64_t)(10*reader->sampleRate));juce::AudioBuffer<float> stereo(2,length);require(reader->read(&stereo,0,length,0,true,true),"organ read");std::vector<float> mono(length);double mean=0;for(int i=0;i<length;++i){mono[i]=(stereo.getSample(0,i)+stereo.getSample(1,i))*.5f;mean+=mono[i];}mean/=length;for(auto& x:mono)x-=mean;
  double ratio=48000/(reader->sampleRate*std::pow(2.,7./12));std::vector<float> shifted((size_t)std::ceil(length*ratio)+256);SRC_DATA data{};data.data_in=mono.data();data.input_frames=length;data.data_out=shifted.data();data.output_frames=(long)shifted.size();data.src_ratio=ratio;data.end_of_input=1;require(src_simple(&data,SRC_SINC_FASTEST,1)==0,"pitch control resampling");juce::AudioBuffer<float> pitch(1,(int)data.output_frames_gen);std::copy(shifted.begin(),shifted.begin()+data.output_frames_gen,pitch.getWritePointer(0));auto pitched=folder.getChildFile("Organ plus seven semitones.wav");require(writeRenderedAudio(pitched,pitch,48000),"pitch control file");files.add(pitched);
  auto countVariants=[&]{sqlite3* db=nullptr;require(sqlite3_open(root.getChildFile("drum-similarity.db").getFullPathName().toRawUTF8(),&db)==SQLITE_OK,"open test cache");sqlite3_stmt* statement=nullptr;sqlite3_prepare_v2(db,"SELECT count(*) FROM query_embeddings",-1,&statement,nullptr);int n=sqlite3_step(statement)==SQLITE_ROW?sqlite3_column_int(statement,0):0;sqlite3_finalize(statement);sqlite3_close(db);return n;};
  DrumSimilarity service(root);service.prepare({folder});require(wait([&]{return !service.state().busy;}),"non-drum preparation completes");require(service.state().completed==5&&service.state().failed==0,"all four non-drum types plus pitch control prepared");
  double lastQueryMs=0;auto query=[&](juce::File file,Mode mode,bool pitch){auto revision=service.state().resultRevision;double began=juce::Time::getMillisecondCounterHiRes();service.find(file,mode,pitch);require(juce::Time::getMillisecondCounterHiRes()-began<10,"query returns promptly");require(wait([&]{return !service.state().queryBusy;}),"query finishes");lastQueryMs=juce::Time::getMillisecondCounterHiRes()-began;auto result=service.state();std::cout<<result.message<<" ("<<juce::Time::getMillisecondCounterHiRes()-began<<" ms)\n";require(result.resultRevision>revision&&result.scores&&result.scores->size()==4,"non-drum query results");return result;};
  auto normal=query(files[0],Mode::General,false);require(countVariants()==1,"general body fingerprint cached");auto changed=query(files[0],Mode::General,true);require(countVariants()==25,"all semitone and body fingerprints cached");require(changed.scores->at(pitched.getFullPathName())<normal.scores->at(pitched.getFullPathName()),"real transposed organ is a closer match with tolerance");std::cout<<"Transposed organ distance: "<<normal.scores->at(pitched.getFullPathName())<<" -> "<<changed.scores->at(pitched.getFullPathName())<<"\n";
  auto stamp=root.getChildFile("drum-similarity.db").getLastModificationTime();auto warm=query(files[0],Mode::General,true);require(lastQueryMs<500,"warm pitch query avoids inference and pacing waits");require(*warm.scores==*changed.scores&&countVariants()==25,"warm pitch search reuses identical fingerprints");query(files[0],Mode::Drums,false);require(countVariants()==25,"drum switch preserves prepared general cache");query(files[0],Mode::General,true);require(countVariants()==25,"switch back uses query cache");
  for(int i=1;i<4;++i)query(files[i],Mode::General,false);
  service.find(files[1],Mode::General,true);require(wait([&]{return service.state().queryCompleted>=2;}),"pitch search progress");service.clear();auto revision=service.state().resultRevision;juce::Thread::sleep(700);require(!service.state().queryBusy&&!service.state().scores&&service.state().resultRevision==revision,"cancelled query cannot restore results");
  // Short decaying sounds must fall back to the whole sound when the body is silent.
  juce::AudioBuffer<float> tail(1,48000);tail.clear();for(int i=0;i<1000;++i)tail.setSample(0,i,.5f*std::sin(i*.1f));auto shortSound=folder.getChildFile("Silent tail.wav");require(writeRenderedAudio(shortSound,tail,48000),"silent-body fixture");service.prepare({shortSound});require(wait([&]{return !service.state().busy;}),"silent-body preparation");service.find(shortSound,Mode::General,false);require(wait([&]{return !service.state().queryBusy;}),"silent body query completes");require(service.state().scores&&service.state().scores->size()==5,"silent body falls back safely");
  std::cout<<"General sound weighting, organ/pad/piano/bell queries, real transposition control, cached 25 variants, mode switching, progress/cancellation and silent-body fallback passed\n";return 0;
 }catch(const std::exception& e){std::cerr<<"FAIL: "<<e.what()<<"\n";return 4311;}
}
